styles:
/* SMSX hl-fix v1 (Oct 19): shirt white bg, gift card art, logo boxes off. Style only; tile hidden. */
#tile-custom-code-KYCFWh{display:none!important}
.sms-hl__feat img{background:#fff!important;filter:brightness(1.09) contrast(1.03)}
.sms-hl__lg a,.sms-hl__lg img{background:transparent!important}
.sms-hl__lg img{mix-blend-mode:multiply}
a.sms-hl__card[href*="gift-card"]{background:#0b0b0b!important;background-image:radial-gradient(120% 70% at 90% 0%,rgba(232,98,44,.42),transparent 60%),radial-gradient(80% 50% at 0% 100%,rgba(232,98,44,.16),transparent 70%)!important;overflow:hidden;min-height:640px}
a.sms-hl__card[href*="gift-card"]::before,a.sms-hl__card[href*="gift-card"]::after{position:absolute;inset:auto;top:56px;left:50%;width:min(78%,380px);aspect-ratio:1.586;box-sizing:border-box;border-radius:18px;transform:translateX(-50%) rotate(-7deg);transition:transform .35s ease}
a.sms-hl__card[href*="gift-card"]::before{content:"Salida\A Mountain\A Sports";white-space:pre;padding:22px 24px;font:400 clamp(28px,8vw,40px)/.88 'Bebas Neue',Impact,sans-serif;letter-spacing:.04em;text-transform:uppercase;color:#fff;background:repeating-radial-gradient(circle at 105% 115%,transparent 0 13px,rgba(255,255,255,.08) 13px 14px),linear-gradient(140deg,#f07a3a 0%,#e8622c 38%,#141414 38.5%,#0b0b0b 100%)!important;box-shadow:0 28px 60px rgba(0,0,0,.65),inset 0 0 0 1px rgba(255,255,255,.18)}
a.sms-hl__card[href*="gift-card"]::after{content:"GIFT CARD";display:flex;align-items:flex-end;justify-content:flex-end;padding:0 24px 20px;font:700 11px/1 'Inter',system-ui,sans-serif;letter-spacing:.3em;color:#e8622c;pointer-events:none}
a.sms-hl__card[href*="gift-card"]:hover::before,a.sms-hl__card[href*="gift-card"]:hover::after{transform:translateX(-50%) translateY(-8px) rotate(-3deg)}
@media(max-width:900px){a.sms-hl__card[href*="gift-card"]{min-height:600px}.sms-hl__feat img{max-height:none}.sms-hl__lg{gap:12px 18px}.sms-hl__lg a{height:56px}.sms-hl__lg img{max-height:46px}}

.sms-hero{position:relative;color:#fff;background:#0c0c0c url("https://images.unsplash.com/photo-1643358598688-2e829316d96f?w=2400&q=75&auto=format&fit=crop") 70% 55%/cover no-repeat;overflow:hidden}
.sms-hero::before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(8,10,12,.78) 0%,rgba(8,10,12,.45) 45%,rgba(8,10,12,.05) 75%),linear-gradient(0deg,rgba(8,10,12,.45) 0%,rgba(8,10,12,0) 35%)}
.sms-hero__inner{position:relative;max-width:1400px;margin:0 auto;min-height:clamp(520px,78vh,820px);display:flex;align-items:center;padding:clamp(48px,6vw,96px) clamp(20px,4vw,56px) clamp(56px,7vw,100px)}
.sms-hero__copy{max-width:640px}
.sms-hero__eyebrow{color:#fff;font-size:15px;font-weight:600;letter-spacing:.18em;text-transform:uppercase;margin:0 0 18px;text-shadow:0 1px 8px rgba(0,0,0,.35)}
.sms-hero__title{color:#fff;font-size:clamp(46px,7vw,100px);font-weight:800;line-height:.95;letter-spacing:-.01em;text-transform:uppercase;margin:0 0 20px;text-shadow:0 2px 18px rgba(0,0,0,.35)}
.sms-hero__sub{color:#f1efe9;font-size:clamp(16px,1.4vw,19px);line-height:1.5;margin:0 0 32px;max-width:520px;text-shadow:0 1px 8px rgba(0,0,0,.4)}
.sms-hero__ctas{display:flex;flex-wrap:wrap;gap:12px}
.sms-hero__btn{display:inline-flex;align-items:center;gap:12px;background:#fff;color:#0c0c0c!important;text-decoration:none;padding:18px 30px;font-size:14px;font-weight:700;letter-spacing:.06em;text-transform:uppercase}
.sms-hero__btn:hover{background:#e8622c;color:#0c0c0c!important}
.sms-hero__btn--ghost{background:transparent;color:#fff!important;box-shadow:inset 0 0 0 2px #fff}
.sms-hero__btn--ghost:hover{background:#fff;color:#0c0c0c!important}
@media (max-width:760px){
  .sms-hero{--sms-hdr:60px;background-position:62% 50%}
  .sms-hero::before{background:linear-gradient(180deg,rgba(8,10,12,.25) 0%,rgba(8,10,12,.55) 55%,rgba(8,10,12,.8) 100%)}
  .sms-hero__inner{min-height:560px;align-items:flex-end;padding-top:48px}
  .sms-hero__btn{padding:16px 22px}
}

.sms-activity-section {
  padding: 40px 24px 20px;
  font-family: inherit;
}

.sms-activity-heading {
  font-size: 32px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #000;
  margin: 0 0 16px 0;
}

.sms-activity-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.sms-activity-tile {
  position: relative;
  border-radius: 8px;
  overflow: hidden;
  aspect-ratio: 3 / 4;
  cursor: pointer;
  text-decoration: none;
  display: block;
}

.sms-activity-tile img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.4s ease;
}

.sms-activity-tile:hover img {
  transform: scale(1.04);
}

.sms-activity-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,0.72) 0%, rgba(0,0,0,0.15) 50%, rgba(0,0,0,0) 100%);
  transition: background 0.3s ease;
}

.sms-activity-tile:hover .sms-activity-overlay {
  background: linear-gradient(to top, rgba(0,0,0,0.82) 0%, rgba(0,0,0,0.25) 60%, rgba(0,0,0,0.05) 100%);
}

.sms-activity-content {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 20px 16px;
}

.sms-activity-title {
  font-size: 17px;
  font-weight: 700;
  color: #ffffff;
  margin: 0 0 5px;
  line-height: 1.2;
}

.sms-activity-sub {
  font-size: 12px;
  color: rgba(255,255,255,0.75);
  margin: 0 0 12px;
  line-height: 1.4;
}

.sms-activity-cta {
  display: inline-block;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #ffffff;
  border: 1.5px solid rgba(255,255,255,0.6);
  border-radius: 3px;
  padding: 5px 10px;
  transition: background 0.2s ease, border-color 0.2s ease;
}

.sms-activity-tile:hover .sms-activity-cta {
  background: rgba(255,255,255,0.15);
  border-color: #ffffff;
}

@media (max-width: 600px) {
  .sms-activity-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 8px;
  }

  .sms-activity-title {
    font-size: 9px !important;
    white-space: normal !important;
    overflow: visible !important;
    text-overflow: unset !important;
    word-break: keep-all !important;
  }

  .sms-activity-content {
    padding: 12px 10px !important;
  }

  .sms-activity-cta {
    font-size: 9px !important;
    padding: 3px 6px !important;
  }

  .sms-activity-sub {
    display: none !important;
  }
}

.sms-hl{background:#fff;color:#0b0b0b;font-family:'Inter',system-ui,sans-serif}
.sms-hl *{box-sizing:border-box}
.sms-hl h2,.sms-hl .sms-hl__t{font-family:'Bebas Neue',Impact,sans-serif;font-weight:400;text-transform:uppercase;line-height:.95;letter-spacing:.02em;margin:0 0 14px}
.sms-hl__eye{color:#e8622c;font-size:12px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;margin:0 0 10px}
.sms-hl__btn{display:inline-block;background:#0b0b0b;color:#fff!important;text-decoration:none!important;padding:15px 26px;font-size:13px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;border:2px solid #0b0b0b}
.sms-hl__btn:hover{background:#e8622c;border-color:#e8622c;color:#0b0b0b!important}
.sms-hl__btn--w{background:#fff;color:#0b0b0b!important;border-color:#fff}
.sms-hl__feat{display:grid;grid-template-columns:1fr 1fr;max-width:1280px;margin:0 auto;padding:72px 40px;gap:48px;align-items:center}
.sms-hl__feat img{width:100%;max-height:560px;object-fit:contain;background:#f3f1ec}
.sms-hl__feat h2{font-size:clamp(40px,5vw,72px)}
.sms-hl__feat p{font-size:17px;line-height:1.6;color:#333;margin:0 0 24px;max-width:520px}
.sms-hl__price{font-size:20px;font-weight:700;margin:0 0 20px}
.sms-hl__duo{display:grid;grid-template-columns:1fr 1fr;gap:0}
.sms-hl__card{position:relative;min-height:520px;display:flex;align-items:flex-end;color:#fff;background:#0b0b0b center/cover no-repeat;text-decoration:none!important}
.sms-hl__card::before{content:"";position:absolute;inset:0;background:linear-gradient(0deg,rgba(0,0,0,.82) 0%,rgba(0,0,0,.25) 55%,rgba(0,0,0,.05) 100%)}
.sms-hl__card>div{position:relative;padding:40px;max-width:560px}
.sms-hl__card h2{color:#fff;font-size:clamp(36px,4vw,60px)}
.sms-hl__card p{color:#e9e6df;font-size:16px;line-height:1.6;margin:0 0 22px}
.sms-hl__logos{background:#f3f1ec;padding:64px 40px;text-align:center}
.sms-hl__logos h2{font-size:clamp(36px,4vw,56px)}
.sms-hl__lg{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:28px 40px;max-width:1200px;margin:28px auto 32px;align-items:center}
.sms-hl__lg a{display:flex;align-items:center;justify-content:center;height:70px}
.sms-hl__lg img{max-width:100%;max-height:60px;object-fit:contain;filter:grayscale(1);opacity:.85;transition:all .2s}
.sms-hl__lg a:hover img{filter:none;opacity:1}
.sms-hl__about{background:#0b0b0b;color:#fff;padding:80px 40px;text-align:center}
.sms-hl__about h2{color:#fff;font-size:clamp(40px,5vw,72px)}
.sms-hl__about p{max-width:820px;margin:0 auto;font-size:17px;line-height:1.7;color:#d6d3cc}
@media(max-width:900px){.sms-hl__feat,.sms-hl__duo{grid-template-columns:1fr}.sms-hl__feat{padding:48px 20px;gap:28px}.sms-hl__card{min-height:420px}.sms-hl__card>div{padding:28px 20px}.sms-hl__lg{grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.sms-hl__logos,.sms-hl__about{padding:48px 20px}}

.sms-faq { max-width: 860px; margin: 0 auto; padding: 64px 24px; font-family: 'Inter',system-ui,sans-serif; color: #111; }
.sms-faq h2 { font-family:'Bebas Neue',Impact,sans-serif; font-size: clamp(40px, 5vw, 64px); font-weight: 400; text-transform:uppercase; margin: 0 0 20px; line-height: .95; }
.sms-faq details { border-bottom: 1px solid #ddd; padding: 16px 0; }
.sms-faq summary { font-size: 18px; font-weight: 600; cursor: pointer; list-style: none; display: flex; justify-content: space-between; gap: 16px; }
.sms-faq summary::-webkit-details-marker { display: none; }
.sms-faq summary::after { content: "+"; font-weight: 400; font-size: 22px; line-height: 1; color:#e8622c; }
.sms-faq details[open] summary::after { content: "\2212"; }
.sms-faq p { font-size: 16px; line-height: 1.55; color: #333; margin: 10px 0 0; }

.sms-visit{background:#121614;color:#f4f1ea;font-family:'Inter',system-ui,sans-serif}
.sms-visit *{box-sizing:border-box}
.sms-visit__grid{display:grid;grid-template-columns:1fr;max-width:1280px;margin:0 auto}
.sms-visit__info{padding:64px 24px}
.sms-visit__eyebrow{color:#e8622c;font-weight:700;letter-spacing:.18em;text-transform:uppercase;font-size:13px;margin:0 0 12px}
.sms-visit h2{font-family:'Bebas Neue',Impact,sans-serif;font-weight:400;font-size:clamp(44px,6vw,72px);line-height:.95;text-transform:uppercase;margin:0 0 24px;color:#f4f1ea}
.sms-visit p{margin:0 0 14px;font-size:17px;line-height:1.55;color:#d9d5cc}
.sms-visit a{color:#f4f1ea}
.sms-visit__addr{font-size:20px!important;color:#f4f1ea!important;font-weight:600}
.sms-visit__hours{list-style:none;margin:0 0 18px;padding:0;max-width:340px}
.sms-visit__hours li{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid #2c332f;font-size:16px;color:#d9d5cc}
.sms-visit__hours b{color:#f4f1ea;font-weight:600}
.sms-visit a.sms-visit__btn,.sms-visit a.sms-visit__btn:visited{display:inline-block;margin:10px 10px 0 0;background:#e8622c;color:#121614!important;text-decoration:none;font-weight:700;text-transform:uppercase;letter-spacing:.12em;font-size:13px;padding:16px 26px}
.sms-visit a.sms-visit__btn--ghost{background:transparent;border:2px solid #f4f1ea;color:#f4f1ea!important;padding:14px 24px}
.sms-visit a.sms-visit__btn:hover{filter:brightness(1.08)}
.sms-visit__map{min-height:360px;background:#121614}
.sms-visit__map a{display:block;height:100%}
.sms-visit__map img{display:block;width:100%;height:100%;min-height:360px;object-fit:cover;object-position:50% 45%}
@media(min-width:900px){.sms-visit__grid{grid-template-columns:1fr 1.3fr}.sms-visit__info{padding:96px 56px}.sms-visit__map,.sms-visit__map img{min-height:520px}}
